import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns
import base64
from io import BytesIO
import json
import os

# Set plotting style
sns.set_theme(style="whitegrid")

def fig_to_base64(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=100)
    plt.close(fig)
    return base64.b64encode(buf.getvalue()).decode('utf-8')

def format_currency(val):
    return f"${val:,.2f}"

def format_number(val):
    return f"{val:,.0f}"

def format_percent(val):
    return f"{val:.1f}%"

def main():
    # 1. Load Data
    print("Loading data...")
    df = pd.read_csv('/app/benchmark/data.csv')

    # 2. Data Preparation
    print("Preparing data...")
    df['order_date'] = pd.to_datetime(df['order_date'])
    df['year_month'] = df['order_date'].dt.to_period('M').astype(str)
    df['quarter'] = df['order_date'].dt.to_period('Q').astype(str)

    # Check for missing data in dimensions
    has_product_dims = 'category' in df.columns or 'brand' in df.columns
    has_store_dims = 'city' in df.columns or 'store_type' in df.columns
    has_customer_dims = 'age' in df.columns or 'loyalty_member' in df.columns

    # 3. Calculate KPIs
    print("Calculating KPIs...")
    total_revenue = df['revenue'].sum()
    total_profit = df['profit'].sum()
    avg_profit_margin = (total_profit / total_revenue) * 100 if total_revenue > 0 else 0
    avg_order_value = df.groupby('order_id')['revenue'].sum().mean()
    discount_utilization = (df['discount'] > 0).mean() * 100

    # 4. Generate Charts
    print("Generating charts...")
    charts = {}

    # --- Sales Trends ---
    monthly_trends = df.groupby('year_month').agg(
        revenue=('revenue', 'sum'),
        profit=('profit', 'sum'),
        orders=('order_id', 'nunique')
    ).reset_index()

    # Sales Trend Chart
    fig, ax1 = plt.subplots(figsize=(12, 6))
    ax1.plot(monthly_trends['year_month'], monthly_trends['revenue'], label='Revenue', color='#4c72b0', marker='o')
    ax1.plot(monthly_trends['year_month'], monthly_trends['profit'], label='Profit', color='#55a868', marker='s')
    ax1.set_xlabel('Month')
    ax1.set_ylabel('Amount ($)')
    ax1.set_title('Monthly Revenue and Profit (2023-2024)', fontsize=14, pad=15)
    ax1.tick_params(axis='x', rotation=45)
    ax1.legend(loc='upper left')
    fig.tight_layout()
    charts['sales_trend'] = fig_to_base64(fig)

    # Order Volume Chart
    fig, ax = plt.subplots(figsize=(12, 5))
    sns.barplot(data=monthly_trends, x='year_month', y='orders', color='#c44e52', ax=ax)
    ax.set_xlabel('Month')
    ax.set_ylabel('Number of Orders')
    ax.set_title('Monthly Order Volume', fontsize=14, pad=15)
    ax.tick_params(axis='x', rotation=45)
    fig.tight_layout()
    charts['order_volume'] = fig_to_base64(fig)

    # --- Product Performance ---
    top_products = df.groupby('product_id').agg(
        revenue=('revenue', 'sum'),
        profit=('profit', 'sum')
    ).sort_values('revenue', ascending=False).head(10).reset_index()

    fig, ax = plt.subplots(figsize=(10, 6))
    sns.barplot(data=top_products, y='product_id', x='revenue', color='#4c72b0', ax=ax)
    ax.set_xlabel('Revenue ($)')
    ax.set_ylabel('Product ID')
    ax.set_title('Top 10 Products by Revenue', fontsize=14, pad=15)
    fig.tight_layout()
    charts['top_products'] = fig_to_base64(fig)

    # --- Store Performance ---
    top_stores = df.groupby('store_id').agg(
        revenue=('revenue', 'sum'),
        orders=('order_id', 'nunique')
    ).sort_values('revenue', ascending=False).head(10).reset_index()

    fig, ax = plt.subplots(figsize=(10, 6))
    sns.barplot(data=top_stores, y='store_id', x='revenue', color='#55a868', ax=ax)
    ax.set_xlabel('Revenue ($)')
    ax.set_ylabel('Store ID')
    ax.set_title('Top 10 Stores by Revenue', fontsize=14, pad=15)
    fig.tight_layout()
    charts['top_stores'] = fig_to_base64(fig)

    # --- Discount Impact ---
    discount_analysis = df.groupby('discount').agg(
        revenue=('revenue', 'sum'),
        profit=('profit', 'sum'),
        orders=('order_id', 'nunique'),
        qty=('quantity', 'sum')
    ).reset_index()
    discount_analysis['margin'] = (discount_analysis['profit'] / discount_analysis['revenue']) * 100
    discount_analysis['avg_order_qty'] = discount_analysis['qty'] / discount_analysis['orders']

    fig, ax1 = plt.subplots(figsize=(10, 6))
    ax2 = ax1.twinx()

    sns.barplot(data=discount_analysis, x='discount', y='avg_order_qty', color='#c44e52', alpha=0.7, ax=ax1)
    sns.lineplot(data=discount_analysis, x=discount_analysis.index, y='margin', color='#4c72b0', marker='o', linewidth=2, ax=ax2)

    ax1.set_xlabel('Discount Level')
    ax1.set_ylabel('Avg Quantity per Order', color='#c44e52')
    ax2.set_ylabel('Profit Margin (%)', color='#4c72b0')
    ax1.set_title('Discount Impact on Order Quantity and Profit Margin', fontsize=14, pad=15)
    fig.tight_layout()
    charts['discount_impact'] = fig_to_base64(fig)

    # --- Customer Insights ---
    # Top customers since demographics are missing
    top_customers = df.groupby('customer_id').agg(
        revenue=('revenue', 'sum'),
        orders=('order_id', 'nunique')
    ).sort_values('revenue', ascending=False).head(10).reset_index()

    fig, ax = plt.subplots(figsize=(10, 6))
    sns.barplot(data=top_customers, y='customer_id', x='revenue', color='#8172b3', ax=ax)
    ax.set_xlabel('Revenue ($)')
    ax.set_ylabel('Customer ID')
    ax.set_title('Top 10 Customers by Revenue', fontsize=14, pad=15)
    fig.tight_layout()
    charts['top_customers'] = fig_to_base64(fig)

    # 5. Generate HTML Report
    print("Generating HTML...")

    html_template = f"""<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Chocolate Retail Sales Performance Report (2023–2024)</title>
